import{_ as t,o as a,c as n,a2 as r}from"./chunks/framework.hw3Av5Vn.js";const m=JSON.parse('{"title":"Rock","description":"","frontmatter":{},"headers":[],"relativePath":"demos/ROCK.md","filePath":"demos/ROCK.md"}'),o={name:"demos/ROCK.md"};function l(s,e,i,c,d,h){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="rock" tabindex="-1">Rock <a class="header-anchor" href="#rock" aria-label="Permalink to &quot;Rock&quot;">​</a></h1><p>The demo songs in the rock style. Each is described below, with the features it uses; <a href="./../DEMOS">About Demos</a> lists every demo.</p><ul><li><a href="#aliens_counting">Synth-Rock</a>: <code>aliens_counting.yml</code></li><li><a href="#annandale">Jazz-Rock</a>: <code>annandale.yml</code></li><li><a href="#green_men">Pop-Punk Strumming</a>: <code>green_men.yml</code></li><li><a href="#know_your_slang">Indie Rock</a>: <code>know_your_slang.yml</code></li><li><a href="#not_werewolves">Outlaw Piano Rock</a>: <code>not_werewolves.yml</code></li><li><a href="#spot_over_there">Power-Pop</a>: <code>spot_over_there.yml</code></li><li><a href="#training_montage">Arena-Rock</a>: <code>training_montage.yml</code></li><li><a href="#volcano">Guitar Showpiece</a>: <code>volcano.yml</code></li></ul><p><a id="aliens_counting"></a></p><h2 id="synth-rock-aliens-counting-yml" tabindex="-1">Synth-Rock: <code>aliens_counting.yml</code> <a class="header-anchor" href="#synth-rock-aliens-counting-yml" aria-label="Permalink to &quot;Synth-Rock: `aliens_counting.yml`&quot;">​</a></h2><p>A mid-eighties synth-rock anthem in the manner of The Final Countdown, with a fanfare of its own in sixteenths on synth brass, over power chords, a pad and a rock beat with crashes.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/rock/aliens_counting.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/rock/aliens_counting.yml</code></a> · F# minor · 118 BPM · 2:59 · 8 scenes · 9 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="annandale"></a></p><h2 id="jazz-rock-annandale-yml" tabindex="-1">Jazz-Rock: <code>annandale.yml</code> <a class="header-anchor" href="#jazz-rock-annandale-yml" aria-label="Permalink to &quot;Jazz-Rock: `annandale.yml`&quot;">​</a></h2><p>A seventies jazz-rock song in the manner of Steely Dan&#39;s My Old School, lightly swung: an electric piano on the scale chord 7, so that the Progression gives each chord the seventh its scale says, and a horn line answered two scale steps below by a transposed second horn track.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/rock/annandale.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/rock/annandale.yml</code></a> · G major · 128 BPM · 3:00 · 8 scenes · 8 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">grooves</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="green_men"></a></p><h2 id="pop-punk-strumming-green-men-yml" tabindex="-1">Pop-Punk Strumming: <code>green_men.yml</code> <a class="header-anchor" href="#pop-punk-strumming-green-men-yml" aria-label="Permalink to &quot;Pop-Punk Strumming: `green_men.yml`&quot;">​</a></h2><p>A pop-punk song in the manner of Green Day and Sum 41 at 180 beats a minute. The guitar track strums every power chord down, tight, as a pick rakes the strings, and in the bridge a Strum generator in the clips&#39; chains wins over the track&#39;s strum and rakes down and up, looser.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/rock/green_men.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/rock/green_men.yml</code></a> · E major · 180 BPM · 3:01 · 9 scenes · 7 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th><th style="text-align:center;">strum</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="know_your_slang"></a></p><h2 id="indie-rock-know-your-slang-yml" tabindex="-1">Indie Rock: <code>know_your_slang.yml</code> <a class="header-anchor" href="#indie-rock-know-your-slang-yml" aria-label="Permalink to &quot;Indie Rock: `know_your_slang.yml`&quot;">​</a></h2><p>An indie rock song in two moods after the Shins&#39; New Slang and Know Your Onion, with melodies of its own: a strummed acoustic guitar with a tambourine, then a jangling electric guitar and a full kit. The acoustic guitar&#39;s track strums down and up.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/rock/know_your_slang.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/rock/know_your_slang.yml</code></a> · G major · 116 BPM · 3:02 · 7 scenes · 8 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th><th style="text-align:center;">strum</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="not_werewolves"></a></p><h2 id="outlaw-piano-rock-not-werewolves-yml" tabindex="-1">Outlaw Piano Rock: <code>not_werewolves.yml</code> <a class="header-anchor" href="#outlaw-piano-rock-not-werewolves-yml" aria-label="Permalink to &quot;Outlaw Piano Rock: `not_werewolves.yml`&quot;">​</a></h2><p>An upbeat honky-tonk piano rock song on the chords of Warren Zevon&#39;s Frank and Jesse James, in its key of F major, with a melody and a solo of its own. It opens like saloon music, a stride left hand under a ragtime right hand, before the band comes in and the upright piano plays the tune in octaves, with a ragtime solo and a quiet ballad scene before the last chorus.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/rock/not_werewolves.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/rock/not_werewolves.yml</code></a> · F major · 106 BPM · 3:01 · 7 scenes · 11 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="spot_over_there"></a></p><h2 id="power-pop-spot-over-there-yml" tabindex="-1">Power-Pop: <code>spot_over_there.yml</code> <a class="header-anchor" href="#power-pop-spot-over-there-yml" aria-label="Permalink to &quot;Power-Pop: `spot_over_there.yml`&quot;">​</a></h2><p>An early-2000s power-pop song in the manner of Stacy&#39;s Mom, with a melody of its own: driving eighth-note power chords, a pick bass and a crash on every chorus bar.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/rock/spot_over_there.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/rock/spot_over_there.yml</code></a> · E major · 120 BPM · 3:04 · 7 scenes · 7 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="training_montage"></a></p><h2 id="arena-rock-training-montage-yml" tabindex="-1">Arena-Rock: <code>training_montage.yml</code> <a class="header-anchor" href="#arena-rock-training-montage-yml" aria-label="Permalink to &quot;Arena-Rock: `training_montage.yml`&quot;">​</a></h2><p>An early-eighties film anthem in the manner of Eye of the Tiger, for a training montage: muted guitar chords hit in a syncopated rhythm with the kick, then a driving rock beat and a brass lead. The rhythm and the melody are its own.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/rock/training_montage.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/rock/training_montage.yml</code></a> · C minor · 108 BPM · 2:58 · 7 scenes · 8 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="volcano"></a></p><h2 id="guitar-showpiece-volcano-yml" tabindex="-1">Guitar Showpiece: <code>volcano.yml</code> <a class="header-anchor" href="#guitar-showpiece-volcano-yml" aria-label="Permalink to &quot;Guitar Showpiece: `volcano.yml`&quot;">​</a></h2><p>A solo guitar showpiece in the manner of Van Halen&#39;s Eruption: the band hits a chord and leaves the guitar alone for runs in thirty-second notes, a trill, and tapped arpeggios, a held chord broken up by an arpeggiator in sixteenth-note triplets.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/rock/volcano.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/rock/volcano.yml</code></a> · E minor · 120 BPM · 2:56 · 6 scenes · 6 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">arps</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table>',43)])])}const y=t(o,[["render",l]]);export{m as __pageData,y as default};
